import{_ as e,o,c as l,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Hotkeys & Gestures","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/hotkeys.md","filePath":"user-guide/hotkeys.md","lastUpdated":1787586465000}'),i={name:"user-guide/hotkeys.md"};function r(n,t,a,d,c,g){return o(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="hotkeys-gestures" tabindex="-1">Hotkeys &amp; Gestures <a class="header-anchor" href="#hotkeys-gestures" aria-label="Permalink to &quot;Hotkeys &amp; Gestures&quot;">​</a></h1><p>Lertaro embraces a keyboard-first interaction philosophy while offering rich mouse gestures and quick cascading navigation. Except for non-configurable core keys, all global and in-app hotkeys can be customized under <a href="./settings/hotkeys-page.html"><strong>Settings → Hotkeys</strong></a>.</p><h2 id="_1-global-hotkeys-cheat-sheet" tabindex="-1">1. Global Hotkeys Cheat Sheet <a class="header-anchor" href="#_1-global-hotkeys-cheat-sheet" aria-label="Permalink to &quot;1. Global Hotkeys Cheat Sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Default Hotkey</th><th style="text-align:left;">Description &amp; Interaction Details</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Toggle Quick Window</strong></td><td style="text-align:left;">Double-tap <code>Ctrl</code></td><td style="text-align:left;">Can be set to a double-tap mode or standard key combinations (e.g. <code>Alt+Space</code>, <code>Win+Space</code>).</td></tr><tr><td style="text-align:left;"><strong>Quick Jump</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">Jumps file dialogs directly to the directory most recently browsed in a supported file manager or Quick Panel.</td></tr><tr><td style="text-align:left;"><strong>Select Next Item</strong></td><td style="text-align:left;"><code>Ctrl+N</code> or <code>↓</code></td><td style="text-align:left;">Moves highlight down. Navigates seamlessly across groups in the Quick Panel.</td></tr><tr><td style="text-align:left;"><strong>Select Previous Item</strong></td><td style="text-align:left;"><code>Ctrl+P</code> or <code>↑</code></td><td style="text-align:left;">Moves highlight up. Navigates seamlessly across groups in the Quick Panel.</td></tr><tr><td style="text-align:left;"><strong>Jump to Results 1–9</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">Modifier is customizable. Number badges appear next to visible items for instant activation.</td></tr><tr><td style="text-align:left;"><strong>Open Action Menu</strong></td><td style="text-align:left;"><code>Ctrl+O</code> or <code>→</code></td><td style="text-align:left;">Expands the context action menu (copy path, properties, run as admin, file operations, etc.).</td></tr><tr><td style="text-align:left;"><strong>Autocomplete from Selection</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">Fills the search box with the selected item&#39;s name or full path for secondary refinement.</td></tr><tr><td style="text-align:left;"><strong>QuickLook Instant Preview</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">Opens or closes the side preview panel (images, documents, audio/video playback, folder trees).</td></tr><tr><td style="text-align:left;"><strong>Previous Search Term</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">Steps backward through recent search query history.</td></tr><tr><td style="text-align:left;"><strong>Next Search Term</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">Steps forward through recent search query history.</td></tr><tr><td style="text-align:left;"><strong>Delete Search History Term</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">Removes the currently displayed keyword from search history.</td></tr><tr><td style="text-align:left;"><strong>Open Full Window</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">Opens the full-sized main search window, carrying over the current query.</td></tr><tr><td style="text-align:left;"><strong>Open LocalSend Window</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">Opens the LocalSend wireless LAN transfer window to quickly send files or text to other devices.</td></tr><tr><td style="text-align:left;"><strong>Pin Window (Keep Visible)</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">Temporarily locks the window open when losing focus (ideal for pasting multi-part queries).</td></tr><tr><td style="text-align:left;"><strong>Toggle Quick Panel</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">Docks the quick panel beside the current active window for recent files, favorites, and workspaces.</td></tr></tbody></table><h2 id="_2-search-box-icon-mouse-gestures" tabindex="-1">2. Search Box Icon &amp; Mouse Gestures <a class="header-anchor" href="#_2-search-box-icon-mouse-gestures" aria-label="Permalink to &quot;2. Search Box Icon &amp; Mouse Gestures&quot;">​</a></h2><p>The small logo inside the search box is not just an indicator — it provides several quick mouse gestures:</p><h3 id="quick-window-icon-gestures" tabindex="-1">Quick Window Icon Gestures <a class="header-anchor" href="#quick-window-icon-gestures" aria-label="Permalink to &quot;Quick Window Icon Gestures&quot;">​</a></h3><ul><li><strong>Left-click</strong>: Pops up the main context menu at the cursor (Show Full Window, Toggle Hotkey, Settings, About, Clean Exit, Exit). &quot;Show Full Window&quot; carries over your active query.</li><li><strong>Left-click &amp; Drag</strong>: Drags the search bar to reposition it. <strong>Holding <code>Ctrl</code> while dragging</strong> locks movement strictly to the <strong>vertical axis</strong>, keeping horizontal alignment intact.</li><li><strong>Right-click</strong>: Instantly resets the Quick Window back to its default centered screen position without altering configured dimensions.</li><li><strong>Middle-click</strong>: Toggles the &quot;Pin Window&quot; state. The logo illuminates while pinned.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Coordinates remembered for the Quick Window are <strong>proportional relative coordinates</strong> on that specific display. When invoked on another monitor with different resolutions or DPI scalings, Lertaro scales position automatically without escaping visible bounds.</p></div><h3 id="inline-and-full-window-icons" tabindex="-1">Inline and Full Window Icons <a class="header-anchor" href="#inline-and-full-window-icons" aria-label="Permalink to &quot;Inline and Full Window Icons&quot;">​</a></h3><ul><li><strong>Inline Window</strong>: When embedded in native file dialogs (Open/Save/Browse), left-clicking the logo triggers the <a href="#3-quick-navigation-mouse-triggers"><strong>Quick Navigation</strong></a> cascading menu; disabled in ordinary Explorer windows.</li><li><strong>Full Window</strong>: Purely decorative.</li></ul><h2 id="_3-quick-navigation-mouse-triggers" tabindex="-1">3. Quick Navigation (Mouse Triggers) <a class="header-anchor" href="#_3-quick-navigation-mouse-triggers" aria-label="Permalink to &quot;3. Quick Navigation (Mouse Triggers)&quot;">​</a></h2><p>Quick Navigation lets you access frequently used directories and recent files with mouse clicks alone without typing.</p><h3 id="triggering-environments" tabindex="-1">Triggering Environments <a class="header-anchor" href="#triggering-environments" aria-label="Permalink to &quot;Triggering Environments&quot;">​</a></h3><ul><li><strong>Desktop Blank Area</strong>: Middle-click (or optional double-left-click) to open the menu. Clicking a folder or file opens it directly.</li><li><strong>File Explorer</strong>: Middle-click empty areas in File Explorer; clicking an item navigates the current window directly to that folder.</li><li><strong>Third-party File Managers</strong>: Middle-click file list areas in Directory Opus, Total Commander, XYplorer, Files, and One Commander (see <a href="./file-manager-support.html"><strong>Supported File Managers</strong></a>).</li><li><strong>File Dialogs</strong>: Middle-click or click the embedded logo inside Open/Save/Browse dialogs to jump instantly to the target folder without accidentally triggering confirmation.</li></ul><h3 id="cascading-menu-structure" tabindex="-1">Cascading Menu Structure <a class="header-anchor" href="#cascading-menu-structure" aria-label="Permalink to &quot;Cascading Menu Structure&quot;">​</a></h3><p>Powered by the <strong>Folder Cascader</strong> plugin:</p><ol><li><strong>Currently Open Folders</strong>: Aggregates and deduplicates active folders from all open file managers.</li><li><strong>Favorites &amp; History</strong>: Lists starred folders, files, and recent visit histories.</li><li><strong>Custom Categories</strong>: Configure nested submenus under <strong>Settings → Plugins → Folder Cascader</strong> (e.g. <code>Work/ProjectA</code>).</li><li><strong>Quick Add Folder (<code>+</code> Button)</strong>: Every submenu header features a small <code>+</code> button to save the currently browsed directory directly into that category.</li></ol><h2 id="_4-hardcoded-core-keys-non-configurable" tabindex="-1">4. Hardcoded Core Keys (Non-configurable) <a class="header-anchor" href="#_4-hardcoded-core-keys-non-configurable" aria-label="Permalink to &quot;4. Hardcoded Core Keys (Non-configurable)&quot;">​</a></h2><p>To ensure consistent and deterministic interaction, the following keys behave identically across all configurations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Context</th><th style="text-align:left;">Standard Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Opens the selected item (file, folder, app, or action).</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Reveals and selects the item in Windows File Explorer.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">Result List</td><td style="text-align:left;">Launches the selected item with administrative privileges.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">Any Context</td><td style="text-align:left;">Clears the query if text exists; closes the window or exits the menu if already empty.</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">Exits the action menu back to the search list when filter text is empty.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> Arrow Keys</td><td style="text-align:left;">Action Menu</td><td style="text-align:left;">Left arrow navigates back to parent menu; right arrow enters submenus.</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">All Lertaro Windows</td><td style="text-align:left;">Suppressed to prevent triggering system titlebar menus on borderless windows.</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">Full / Settings Windows</td><td style="text-align:left;">Closes window normally; suppressed on Quick, Inline, and Preview floating windows.</td></tr></tbody></table><h2 id="_5-plugin-action-hotkeys-process-blacklist" tabindex="-1">5. Plugin Action Hotkeys &amp; Process Blacklist <a class="header-anchor" href="#_5-plugin-action-hotkeys-process-blacklist" aria-label="Permalink to &quot;5. Plugin Action Hotkeys &amp; Process Blacklist&quot;">​</a></h2><h3 id="plugin-action-hotkeys" tabindex="-1">Plugin Action Hotkeys <a class="header-anchor" href="#plugin-action-hotkeys" aria-label="Permalink to &quot;Plugin Action Hotkeys&quot;">​</a></h3><p>Plugins can register specific action shortcuts (e.g. <code>Ctrl+Shift+C</code> for copying paths, or file operations: Cut <code>Ctrl+X</code>, Copy <code>Ctrl+C</code>, Paste <code>Ctrl+V</code>, Delete <code>Delete</code>, Permanent Delete <code>Shift+Delete</code>). Manage and rebind them under <strong>Settings → Hotkeys → Plugin Actions</strong>.</p><h3 id="process-blacklist-fullscreen-bypass" tabindex="-1">Process Blacklist &amp; Fullscreen Bypass <a class="header-anchor" href="#process-blacklist-fullscreen-bypass" aria-label="Permalink to &quot;Process Blacklist &amp; Fullscreen Bypass&quot;">​</a></h3><ul><li><strong>Automatic Fullscreen Bypass</strong>: When a focused foreground application runs in exclusive fullscreen mode (e.g. 3D games or video players), Lertaro automatically bypasses all global hotkeys to avoid interrupting gameplay.</li><li><strong>Custom Process Blacklist</strong>: Add executable names under <a href="./settings/hotkeys-page.html#process-blacklist"><strong>Settings → Hotkeys</strong></a> (e.g. <code>game.exe</code>) to silence hotkeys and mouse triggers while that process is focused.</li></ul>',26)])])}const y=e(i,[["render",r]]);export{h as __pageData,y as default};
